\begin{equation} \label{cos-small}
\bigl| \cos \bigl(\pi \varrho 2^{-k-1}\bigr) \bigr| = \Bigl| \frac{1}{2} \Bigl(1 + e(\varrho 2^{-k-1})\Bigr) \Bigr| \leq \cos \Bigl(\frac{\pi}{4}\Bigr) = \frac{\sqrt{2}}{2}<1.   
\end{equation}

\begin{align*} 
\left\{ \frac{\varrho}{2^{k+1}} \right\}  &= \sum_{\ell=0}^k \mathtt d_{\ell}(\varrho) 2^{\ell - (k+1)}  \\ 
&= \sum_{\ell=0}^{k-2} \mathtt d_{\ell}(\varrho) 2^{\ell - (k+1)} + \mathtt d_{k-1}(\varrho) 2^{-2} + \mathtt d_k(\varrho) 2^{-1} \\ 
&\leq 2^{-(k+1)} \sum_{\ell=0}^{k-2} 2^{\ell} + \begin{cases} \frac{1}{2} &\text{ if } (\mathtt d_{k-1}, \mathtt d_k) = (0,1), \\ 
\frac{1}{4} &\text{ if }  (\mathtt d_{k-1}, \mathtt d_k) = (1,0),
