 &\leq \begin{cases}
 \frac{3}{4} - 2^{-k-1} &\text{ if }  (\mathtt d_{k-1}, \mathtt d_k) = (0,1), \\ 
 \frac{1}{2} - 2^{-k-1} &\text{ if }  (\mathtt d_{k-1}, \mathtt d_k) = (1,0).
 \end{cases} 
\end{align*}

