 \label{omega-lemma} 
The non-decreasing function 
\begin{equation}  \omega(x) := \lfloor  \sqrt{\log x} \rfloor, \qquad x > 0 \label{def-omega}  \end{equation}  
obeys the following ``slow growth'' property. Namely, for every $\mathtt M \in (1, \infty)$ and every $\tau > 0$, there exists $\mathtt X = \mathtt X(\mathtt M, \tau)$ such that 
\begin{equation} \label{omega-inequalities} 
\omega(x) \leq \omega(\mathtt M x) \leq (1 + \tau) \omega(x) \quad \text{ for all } x \geq \mathtt X. 
\end{equation}

\begin{equation} \label{omega-inequalities} 
\omega(x) \leq \omega(\mathtt M x) \leq (1 + \tau) \omega(x) \quad \text{ for all } x \geq \mathtt X. 
\end{equation}

 \label{Omega-cor} 
Let $\Omega(x) := x \omega(x)$, where $\omega$ is any function on $(0,\infty)$ obeying \eqref{omega-inequalities}. Then for every $N \in (1, \infty)$ and $\kappa > 0$, the inequality
\begin{equation} \label{Omega-inequality}
\Omega \bigl(N(1 - \kappa)x \bigr) < N \Omega(x) \text{ holds for all sufficiently large $x > 0$.}
\end{equation}  
In particular, \eqref{Omega-inequality} holds for $\omega$ as in \eqref{def-omega}.

\begin{equation} \label{Omega-inequality}
\Omega \bigl(N(1 - \kappa)x \bigr) < N \Omega(x) \text{ holds for all sufficiently large $x > 0$.}
\end{equation}

 \label{special-tT-lemma} 
Suppose that $K_{\ell}$ is given by \eqref{choice-of-K-epsilon}, and that for any $R \in \mathbb N$, the indices $\mathtt t$ and $\mathtt T$ are defined by the conditions \eqref{t&T}. Then for every $\kappa > 0$, 
\begin{equation} \label{tT-similar}
2 (\mathtt t - 1)(1 - \kappa) < \mathtt T < 2\mathtt t+1 \quad \text{ for all sufficiently large $R$.}
\end{equation} 
As a result, there exist absolute constants $0< c_0 < 1 < C_0$ such that 
\begin{equation} \label{T-t} 
c_0\mathtt T \leq \mathtt T-\mathtt t \leq C_0 \mathtt T \quad  \text{ for all } R \in \mathbb N. 
\end{equation}

\begin{equation} \label{tT-similar}
2 (\mathtt t - 1)(1 - \kappa) < \mathtt T < 2\mathtt t+1 \quad \text{ for all sufficiently large $R$.}
\end{equation}

\begin{equation} \label{T-t} 
c_0\mathtt T \leq \mathtt T-\mathtt t \leq C_0 \mathtt T \quad  \text{ for all } R \in \mathbb N. 
\end{equation}


For any choice of $R \in \mathbb N$, the defining conditions of $\mathtt t$ and $\mathtt T$ given by \eqref{t&T} yield
\[ K_{\mathtt t-1}^2 < R \leq K_{\mathtt t}^2 \quad \text{ and } \quad K_{\mathtt T-1} < R \leq K_{\mathtt T}. \] 
Combining the two inequalities above leads to
\[
K_{\mathtt t-1}^2 = K^{2 \Omega(\mathtt t -1)} < K_{\mathtt T} = K^{\Omega(\mathtt T)} \quad \text{ and } \quad 
K_{\mathtt T-1} = K^{\Omega(\mathtt T-1)} < K_{\mathtt t}^2 = K^{2 \Omega(\mathtt t)}, 
\]
where $\Omega(x) := x \omega(x)$, with $\omega$ as in \eqref{def-omega}. In other words, 
\begin{equation}  \label{2-inequalities}
2 \Omega(\mathtt t -1) < \Omega(\mathtt T) \quad \text{ and } \quad \Omega(\mathtt T-1) < 2 \Omega(\mathtt t). 
\end{equation}  
The first inequality in \eqref{2-inequalities} combined with Corollary \ref{Omega-cor} says that for every $\kappa > 0$, 
\begin{equation}  \label{T-t-left}
\Omega(2(\mathtt t-1)(1 - \kappa)) \leq 2 \Omega(\mathtt t-1) < \Omega(\mathtt T). 
\end{equation} 
The second inequality in  \eqref{2-inequalities} gives, in view of the non-decreasing nature of $\omega$,  
\begin{equation} \label{T-t-right}  
\Omega(\mathtt T -1) < 2 \Omega(\mathtt t) = 2 \mathtt t \omega(\mathtt t)  \leq 2 \mathtt t \omega(2 \mathtt t) = \Omega(2\mathtt t). 
\end{equation}  
Since $\Omega$ is strictly increasing, the inequalities \eqref{T-t-left} and \eqref{T-t-right} lead to the conclusion \eqref{tT-similar}. The deduction of \eqref{T-t} from \eqref{tT-similar} is left to the reader.

